// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *BusinessUnit) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, BusinessUnitTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range businessUnitSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, BusinessUnitTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: BusinessUnitTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, BusinessUnitTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

